#!/usr/bin/env node
/**
 * Regression checks for the launcher's update path.
 *
 * Each check here corresponds to a defect that actually shipped:
 *
 *   1. Manifests announced 1.2.5 with the 1.2.5 sha256 while primary/mirror/urls
 *      still named the 1.2.4 installer. updater.js verifies EVERY candidate against
 *      the same hash, so the "mirror" was a guaranteed failure on exactly the branch
 *      where it gets used.
 *   2. docs/launcher.json (the launcher's PRIMARY feed on GitHub Pages) was never
 *      regenerated by release.sh and drifted a release behind site/.
 *   3. /latest/VOID-Client-Setup.exe resolves by FILENAME inside the newest release,
 *      so a stale name there 404s even though "latest" itself is valid.
 *   4. updater.js left its 10-minute abort timer armed on the success path, keeping
 *      the Electron main process alive after the update had been staged.
 *
 * Usage: node verify_launcher.js [--net]
 *   --net  also exercise the real download() against a small remote file
 */
'use strict';

const fs = require('fs');
const path = require('path');

const ROOT = __dirname;
const MANIFESTS = [
  'site/launcher.json',
  'site/launcher-site.json',
  'docs/launcher.json',
  'docs/launcher-site.json',
];
const PAGES = ['site/index.html', 'site/download.html', 'docs/index.html', 'docs/download.html'];

let pass = 0;
let fail = 0;
const check = (name, ok, detail) => {
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? `  — ${detail}` : ''}`);
  ok ? pass++ : fail++;
};

/* ---------------------------------------------------------------- 1. manifests */
console.log('=== 1. launcher manifests are self-consistent ===');
const manifests = MANIFESTS.map((rel) => ({ rel, json: JSON.parse(fs.readFileSync(path.join(ROOT, rel), 'utf8')) }));

for (const { rel, json: m } of manifests) {
  const w = (m.platforms && m.platforms.win32) || {};
  const urls = [w.url, w.primary, w.mirror, ...(w.urls || [])].filter(Boolean);
  const versions = [...new Set(urls.map((u) => (u.match(/v?(\d+\.\d+\.\d+)/) || [])[1]).filter(Boolean))];

  check(`${rel}: has a version`, /^\d+\.\d+\.\d+$/.test(String(m.version)), `version=${m.version}`);
  check(
    `${rel}: every mirror serves ${m.version}`,
    urls.length > 0 && versions.length === 1 && versions[0] === m.version,
    `urls=[${versions.join(', ')}]`,
  );
  check(
    `${rel}: sha256 is a real digest`,
    /^[0-9a-f]{64}$/.test(String(w.sha256 || '')),
    `${String(w.sha256 || '').slice(0, 12)}…`,
  );
  // release.sh refuses to package anything under 50 MB; the feed must agree, or a
  // truncated NSIS stub would look like a valid update.
  // A Linux entry is optional (a release may ship Windows only) — but if it exists it must
  // point at the AppImage, not at the Windows installer, and its hash must be the real file's.
  const l = (m.platforms && m.platforms.linux) || null;
  if (l) {
    const lurls = [l.url, l.primary, l.mirror, ...(l.urls || [])].filter(Boolean);
    check(`${rel}: linux URLs name the AppImage`, lurls.every((u) => u.includes('.AppImage')), lurls.join(' | '));
    check(`${rel}: linux sha256 present`, /^[0-9a-f]{64}$/.test(String(l.sha256 || '')));
    const localApp = path.join(ROOT, 'dist-linux', `VOID-Client-${m.version}-x86_64.AppImage`);
    if (fs.existsSync(localApp)) {
      const sha = require('crypto').createHash('sha256').update(fs.readFileSync(localApp)).digest('hex');
      check(`${rel}: linux sha matches the built AppImage`, sha === l.sha256, `${l.sha256.slice(0, 12)}… vs ${sha.slice(0, 12)}…`);
      check(`${rel}: linux size matches`, fs.statSync(localApp).size === l.size);
    }
    // A linux entry while win32 exists means pickAsset() must not fall through: the two
    // platform keys have to stay distinct or a Linux user gets offered the .exe.
    check(`${rel}: win32 and linux point at different files`,
      !lurls.some((u) => u.includes('-Setup.exe')));
  }
}

const linuxPresent = manifests.some((x) => x.json.platforms && x.json.platforms.linux);
console.log(`   (linux manifest entry: ${linuxPresent ? 'present' : 'absent'})`);

const versions = [...new Set(manifests.map((x) => x.json.version))];
check('site/ and docs/ announce the same version', versions.length === 1, versions.join(', '));
check(
  'site/ and docs/ manifests are byte-identical per pair',
  fs.readFileSync(path.join(ROOT, 'site/launcher.json'), 'utf8') ===
    fs.readFileSync(path.join(ROOT, 'docs/launcher.json'), 'utf8') &&
    fs.readFileSync(path.join(ROOT, 'site/launcher-site.json'), 'utf8') ===
      fs.readFileSync(path.join(ROOT, 'docs/launcher-site.json'), 'utf8'),
);

const currentVersion = versions[0];
const currentExe = `VOID-Client-${currentVersion}-Setup.exe`;

/* ---------------------------------------------------------------------- 2. pages */
console.log('\n=== 2. download pages point at the current installer ===');
for (const rel of PAGES) {
  const html = fs.readFileSync(path.join(ROOT, rel), 'utf8');
  const links = [...html.matchAll(/VOID-Client-\d+\.\d+\.\d+-Setup\.exe/g)].map((m) => m[0]);
  const stray = links.filter((l) => l !== currentExe);
  check(`${rel}: no stale installer filename`, stray.length === 0, stray.length ? stray.join(', ') : `${links.length} links`);
  const staleTags = [...html.matchAll(/\/releases\/download\/(v\d+\.\d+\.\d+)\//g)]
    .map((m) => m[1])
    .filter((v) => v !== `v${currentVersion}`);
  check(`${rel}: no stale release tag in hrefs`, staleTags.length === 0, [...new Set(staleTags)].join(', '));
  const sha = (html.match(/\b[0-9a-f]{64}\b/) || [])[0];
  check(`${rel}: published checksum matches the manifest`, !sha || sha === manifests[0].json.platforms.win32.sha256);
}

/* ------------------------------------------------------------------ 3. redirects */
console.log('\n=== 3. _redirects ===');
const redirects = fs.readFileSync(path.join(ROOT, 'site/_redirects'), 'utf8').split('\n').filter((l) => l.trim() && !l.trim().startsWith('#'));
const latestRules = redirects.filter((l) => l.startsWith('/latest/'));
// Each artifact gets its own alias, so the count is per-name — not "one alias total", which
// stopped being true the moment the AppImage got one too.
const exeAlias = redirects.filter((l) => l.startsWith('/latest/VOID-Client-Setup.exe'));
check('exactly one /latest alias for the installer', exeAlias.length === 1, `${exeAlias.length} of ${latestRules.length}`);
check(
  '/latest installer alias names the current asset',
  exeAlias.length === 1 && exeAlias[0].includes(`/${currentExe}`),
  exeAlias[0] || '',
);
const appAlias = redirects.filter((l) => l.startsWith('/latest/VOID-Client.AppImage'));
if (appAlias.length) {
  check('exactly one /latest alias for the AppImage', appAlias.length === 1, `${appAlias.length}`);
  check('/latest AppImage alias names the AppImage', appAlias[0].includes('.AppImage'), appAlias[0]);
  check('/latest AppImage alias never names the .exe', !appAlias[0].includes('-Setup.exe'));
}
const strayLatest = latestRules.filter(
  (l) => !l.startsWith('/latest/VOID-Client-Setup.exe') && !l.startsWith('/latest/VOID-Client.AppImage'),
);
check('no unexpected /latest aliases', strayLatest.length === 0, strayLatest.join(' | '));
check(
  `pinned rule for ${currentExe} exists`,
  redirects.some((l) => l.startsWith(`/${currentExe}`)),
);
const badPinned = redirects
  .filter((l) => l.startsWith('/VOID-Client-'))
  .filter((l) => {
    const want = l.split(/\s+/)[0].replace(/^\//, '');
    const target = (l.split(/\s+/)[1] || '').split('/').pop();
    return want !== target; // pinned rule must resolve to a file of the same name
  });
check('every pinned rule targets its own filename', badPinned.length === 0, badPinned.join(' | '));

/* ------------------------------------------------- 4b. the mod must NOT be on the web */
console.log('\n=== 4b. mod is launcher-only: no feed, no web download ===');
for (const rel of ['docs/voidfps.json', 'site/voidfps.json']) {
  check(`${rel}: not published`, !fs.existsSync(path.join(ROOT, rel)));
}
check('scripts/update-mod-feed.js removed', !fs.existsSync(path.join(ROOT, 'scripts/update-mod-feed.js')));
const releaseSh = fs.readFileSync(path.join(ROOT, 'scripts/release.sh'), 'utf8');
check('release.sh does not publish a mod feed', !/voidfps\.json/.test(releaseSh));
// Any leftover URL in the deployable pages would be a web path to the mod.
for (const rel of ['site/index.html', 'site/download.html', 'site/mods.html', 'docs/index.html', 'docs/download.html']) {
  const html = fs.readFileSync(path.join(ROOT, rel), 'utf8');
  check(`${rel}: no link to a bundled mod jar`, !/void-(?:fps|client)-\d[^"']*\.jar/.test(html));
}
// The jar itself stays: it is the build input electron-builder copies into the installer.
const vendorJars = fs.readdirSync(path.join(ROOT, 'vendor')).filter((f) => /^void-(?:fps|client)-.*\.jar$/i.test(f));
check('exactly one bundled mod jar in vendor/', vendorJars.length === 1, vendorJars.join(', '));
// ...and the mod must not be pointing at any feed of ours, or removing the files broke it.
const modUpdater = fs.readFileSync('/home/agung/void-client-mod/src/main/java/id/agung/voidfps/VoidUpdater.java', 'utf8');
check('mod updater has no update URL', /UPDATE_URL = "";/.test(modUpdater));
check('mod autoUpdate defaults off', /public static boolean autoUpdate = false;/.test(modUpdater));

/* ------------------------------------------------------------ 5. manifest writer */
console.log('\n=== 4. update-site.js is idempotent (re-running must not churn) ===');
const { execFileSync } = require('child_process');
const before = MANIFESTS.map((rel) => fs.readFileSync(path.join(ROOT, rel), 'utf8')).join('');
const w = manifests[0].json.platforms.win32;
execFileSync('node', ['scripts/update-site.js', currentVersion, w.sha256, String(w.size), manifests[0].json.notes], { cwd: ROOT, stdio: 'pipe' });
const after = MANIFESTS.map((rel) => fs.readFileSync(path.join(ROOT, rel), 'utf8')).join('');
check('second run produces identical manifests', before === after);

/* ----------------------------------------------------------------- 5. timer leak */
console.log('\n=== 5. updater.js does not leak its abort timer ===');
(async () => {
  if (process.argv.includes('--net')) {
    // Stub electron so the module can be required outside the app.
    const Module = require('module');
    const orig = Module._load;
    Module._load = function (req, ...rest) {
      if (req === 'electron') return { shell: { showItemInFolder: async () => {} } };
      return orig.apply(this, [req, ...rest]);
    };
    const up = require(path.join(ROOT, 'src/main/updater.js'));
    const staged = up.stagedPath('verify');
    fs.rmSync(staged, { force: true });
    const r = await up.download({ version: 'verify', url: 'https://mitsuohiroshi927-png.github.io/void-client/launcher.json' });
    fs.rmSync(staged, { force: true });
    const timers = (process.getActiveResourcesInfo ? process.getActiveResourcesInfo() : []).filter((h) => /timeout|timer/i.test(h));
    check('no timer survives a successful download', r.ok && timers.length === 0, `ok=${r.ok} timers=${timers.length}`);
  } else {
    // Static check: the success path must clear before returning.
    const src = fs.readFileSync(path.join(ROOT, 'src/main/updater.js'), 'utf8');
    const successReturn = src.indexOf('return { ok: true, file: dest');
    const window = src.slice(Math.max(0, successReturn - 260), successReturn);
    check('clearTimeout runs before the successful return', /clearTimeout\(timer\)/.test(window));
  }
  /* ---------------------- 6. bundled mod gate is decided by the jar ------------------------ */
  // A hand-rolled version table used to decide this, and it disagreed with the jar it was
  // describing: it allowed 26.x while the jar declares `minecraft: "1.21.11"`. Fabric then
  // got a jar it refuses to load. The gate now reads the jar's own dependency, and this
  // section runs the REAL buildLaunchSpec so the resulting command line is checked, not a
  // copy of the rule.
  console.log('\n=== 6. the bundled VOID Client jar decides which Minecraft versions it loads on ===');
  const os = require('os');
  const mcver = require(path.join(ROOT, 'src/main/mcver.js'));
  const modsMod = require(path.join(ROOT, 'src/main/mods.js'));
  const launchMod = require(path.join(ROOT, 'src/main/launch.js'));
  Object.defineProperty(process, 'resourcesPath', { value: ROOT, configurable: true });

  for (const [declared, actual, want] of [
    ['1.21.11', '1.21.11', true],
    ['1.21.11', '1.21.10', false],
    ['1.21.11', '26.3', false],
    ['>=1.21.11 <1.22', '1.21.11', true],
    ['>=1.21.11 <1.22', '1.21.4', false],
    ['[1.21.11,1.22)', '1.21.11', true],
    ['[1.21.11,1.22)', '1.22', false],
    ['*', '26.3', true],
    ['bogus', '1.21.11', null],
  ]) {
    const got = mcver.satisfies(declared, actual);
    check(`satisfies(${JSON.stringify(declared)}, ${actual}) is ${want}`, got === want, `got ${got}`);
  }

  const vendorJar = path.join(ROOT, 'vendor', vendorJars[0]);
  const vendorMeta = await modsMod.readFabricModJson(vendorJar);
  const declaredMc = vendorMeta && vendorMeta.depends && vendorMeta.depends.minecraft;
  check('bundled jar declares its Minecraft range', typeof declaredMc === 'string' && declaredMc.length > 0, String(declaredMc));
  check(`bundled jar loads on 1.21.11 (declared ${declaredMc})`, mcver.satisfiesMinecraft(declaredMc, '1.21.11'));
  check('bundled jar is never attached to a version it refuses',
    !mcver.satisfiesMinecraft(declaredMc, '1.21.4') && !mcver.satisfiesMinecraft(declaredMc, '26.3'));

  const fakeVersionJson = {
    id: 'verify', mainClass: 'net.minecraft.client.main.Main',
    libraries: [],
    arguments: {
      jvm: ['-Djava.library.path=${natives_directory}', '-cp', '${classpath}'],
      game: ['--gameDir', '${game_directory}'],
    },
    downloads: {}, assetIndex: { id: 'verify' },
  };
  const builtRoots = [];
  const buildFor = async (mcVersion) => {
    const root = fs.mkdtempSync(path.join(os.tmpdir(), 'void-launch-'));
    builtRoots.push(root);
    const game = path.join(root, 'game');
    fs.mkdirSync(path.join(root, 'versions', mcVersion), { recursive: true });
    fs.writeFileSync(path.join(root, 'versions', mcVersion, `${mcVersion}.jar`), '');
    const modsDir = path.join(game, 'profiles', 'pvp', 'mods');
    fs.mkdirSync(modsDir, { recursive: true });
    fs.writeFileSync(path.join(modsDir, 'sodium.jar'), '');
    const lines = [];
    const spec = await launchMod.buildLaunchSpec({
      root, mcVersion, fabric: null, versionJson: fakeVersionJson,
      session: { name: 'verify', uuid: 'verify', accessToken: 'verify' },
      settings: {
        gameDir: game, profile: 'pvp',
        profileMods: { voidFps: true, inheritShared: false, extraJar: true },
        profileModsDir: modsDir,
        ram: 2048, width: 854, height: 480,
        onLog: (line) => lines.push(line),
      },
    });
    const addMods = spec.args.find((a) => a.startsWith('-Dfabric.addMods=')) || '';
    return { addMods, lines };
  };

  const on111 = await buildFor('1.21.11');
  check('1.21.11: the bundled jar is handed to Fabric', on111.addMods.includes(vendorJars[0]),
    on111.addMods.split(path.delimiter).map((f) => path.basename(f)).join(' + ') || '(no addMods)');
  check('1.21.11: the profile mods folder is attached with it', on111.addMods.includes('sodium.jar'));

  const onOld = await buildFor('1.21.4');
  check('1.21.4: the bundled jar is not attached', !onOld.addMods.includes(vendorJars[0]), onOld.addMods || '(no addMods)');
  check('1.21.4: the skip is reported instead of silent',
    onOld.lines.some((l) => /VOID Client skipped/.test(l)),
    onOld.lines.filter((l) => /VOID Client/.test(l)).join(' | ') || '(nothing logged)');

  const onYear = await buildFor('26.3');
  check('26.3: the bundled jar is not attached', !onYear.addMods.includes(vendorJars[0]), onYear.addMods || '(no addMods)');
  check('26.3: the skip is reported instead of silent',
    onYear.lines.some((l) => /VOID Client skipped/.test(l)),
    onYear.lines.filter((l) => /VOID Client/.test(l)).join(' | ') || '(nothing logged)');

  for (const dir of builtRoots) fs.rmSync(dir, { recursive: true, force: true });

  // The handler must launch what the profile card promises. Global settings used to win,
  // so the version on the card and the version in the game could differ.
  const mainSrc = fs.readFileSync(path.join(ROOT, 'src/main/main.js'), 'utf8');
  const launchSrc = fs.readFileSync(path.join(ROOT, 'src/main/launch.js'), 'utf8');
  check('launch resolves the version from the active profile', /const mcVersion = prof\.mcVersion \|\| s\.mcVersion/.test(mainSrc));
  check('launch resolves the loader from the active profile', /const useFabric = prof\.loader \?/.test(mainSrc));
  check('buildLaunchSpec is called with that version', /buildLaunchSpec\(\{[\s\S]{0,200}?mcVersion,/.test(mainSrc));
  check('launch.js messages reach the launch log', /onLog: \(line\) => send\('launch:log'/.test(mainSrc));
  check('no hand-rolled version table left in launch.js', !/voidFpsSupportsVersion/.test(launchSrc));
  check('the gate reads the jar via mcver', /mcver\.satisfies\(voidFpsDeclared/.test(launchSrc));
  // The regression that made the bundled mod silently never load: the gate read
  // settings.mcVersion, a field the launch handler never sends.
  check('the gate uses the mcVersion parameter, not settings.mcVersion', !/settings\.mcVersion/.test(launchSrc));
  check('a missing bundle is reported', /VOID Client bundle not found/.test(launchSrc));

  // The Mods page and the launch path must agree on where the bundled jar lives. Running from
  // the repo, that is ./vendor — listing the cwd alone never finds it, and the page then says
  // "missing" for a jar that is sitting right there.
  const modsProbe = require(path.join(ROOT, 'src/main/mods.js'));
  const foundJar = await modsProbe.findVoidFpsJar('');
  check('the bundled jar is found from the source tree', Boolean(foundJar) && /vendor[\\/]void-client-.*\.jar$/.test(foundJar), String(foundJar));
  check('and the search also covers a vendor/ folder next to the launcher',
    /path\.join\(process\.cwd\(\), 'vendor'\)/.test(fs.readFileSync(path.join(ROOT, 'src/main/mods.js'), 'utf8')));
  // One version number for the launcher and the mod it bundles, on purpose.
  check('the bundled mod jar carries the release version',
    String(vendorMeta && vendorMeta.version) === String(currentVersion),
    `jar ${vendorMeta && vendorMeta.version} vs release ${currentVersion}`);

  /* ------------------ 7. auto update chain: check → download → verified file ---------------- */
  // The launcher updates itself with no clicks (autoInstall, default on). That path is only
  // as good as the pieces under it, so this runs the REAL check() and download() against a
  // local manifest server: a newer version is detected, the installer is fetched and
  // hash-verified, a bad mirror is skipped, and a hash mismatch is refused outright.
  console.log('\n=== 7. auto update chain (local manifest, no internet) ===');
  const http = require('http');
  const crypto2 = require('crypto');
  if (!global.__electronStubbed) {
    const Module2 = require('module');
    const origLoad2 = Module2._load;
    Module2._load = function (req, ...rest) {
      if (req === 'electron') return { shell: { showItemInFolder: async () => {} } };
      return origLoad2.apply(this, [req, ...rest]);
    };
    global.__electronStubbed = true;
  }
  const updater = require(path.join(ROOT, 'src/main/updater.js'));

  const payload = Buffer.alloc(192 * 1024, 7);
  const digest = crypto2.createHash('sha256').update(payload).digest('hex');
  let feedPort = 0;
  const assetUrl = () => `http://127.0.0.1:${feedPort}/VOID-Client-99.0.0-Setup.exe`;
  const manifestFor = (version) => ({
    version,
    notes: 'local verification feed',
    url: assetUrl(),
    sha256: digest,
    size: payload.length,
    platforms: {
      linux: { url: assetUrl(), sha256: digest, size: payload.length },
      win32: { url: assetUrl(), sha256: digest, size: payload.length },
    },
  });
  const served = [];
  const server = http.createServer((req, res) => {
    served.push(req.url);
    if (req.url === '/launcher.json') {
      res.writeHead(200, { 'content-type': 'application/json' });
      res.end(JSON.stringify(manifestFor('99.0.0')));
      return;
    }
    if (req.url === '/older.json') {
      res.writeHead(200, { 'content-type': 'application/json' });
      res.end(JSON.stringify(manifestFor('1.0.0')));
      return;
    }
    if (req.url === '/VOID-Client-99.0.0-Setup.exe') {
      res.writeHead(200, { 'content-length': String(payload.length) });
      res.end(payload);
      return;
    }
    res.writeHead(404);
    res.end('not here');
  });
  await new Promise((r) => server.listen(0, '127.0.0.1', r));
  feedPort = server.address().port;
  const feed = (p) => `http://127.0.0.1:${feedPort}${p}`;

  const found = await updater.check({ current: '1.2.7', manifestUrl: feed('/launcher.json') });
  check('a newer build is detected', found.ok && found.updateAvailable && found.latest === '99.0.0',
    `ok=${found.ok} latest=${found.latest} available=${found.updateAvailable}`);
  check('the manifest\'s asset is picked for this platform', found.sha256 === digest && found.url === assetUrl(),
    `${String(found.url).slice(0, 48)}…`);
  check('the notes travel with it (the UI shows them)', /local verification feed/.test(String(found.notes)));

  const older = await updater.check({ current: '99.0.0', manifestUrl: feed('/older.json') });
  check('an older manifest is reported as a downgrade, not an update',
    older.ok && !older.updateAvailable && older.downgrade, `available=${older.updateAvailable} downgrade=${older.downgrade}`);

  const autoVersion = '99.0.0-auto';
  const got = await updater.download({ version: autoVersion, url: feed('/VOID-Client-99.0.0-Setup.exe'), sha256: digest });
  const staged = updater.stagedPath(autoVersion);
  check('the installer downloads and is hash-verified', got.ok && got.verified, `ok=${got.ok} verified=${got.verified} ${got.error || ''}`);
  check('the verified file is what the manifest promised',
    fs.existsSync(staged) && crypto2.createHash('sha256').update(fs.readFileSync(staged)).digest('hex') === digest);
  fs.rmSync(staged, { force: true });

  const badHash = await updater.download({ version: '99.0.0-badhash', url: feed('/VOID-Client-99.0.0-Setup.exe'), sha256: 'f'.repeat(64) });
  check('a hash mismatch is refused', !badHash.ok, JSON.stringify(badHash.error || ''));
  check('nothing is left on disk after a refused download',
    !fs.existsSync(updater.stagedPath('99.0.0-badhash')), updater.stagedPath('99.0.0-badhash'));

  const mirrorVersion = '99.0.0-mirror';
  const mirrored = await updater.download({
    version: mirrorVersion,
    urls: [feed('/dead-mirror.exe'), feed('/VOID-Client-99.0.0-Setup.exe')],
    sha256: digest,
  });
  check('a dead mirror does not block the update', mirrored.ok && mirrored.verified,
    `ok=${mirrored.ok} tried=${served.filter((u) => /mirror|Setup/.test(u)).length} urls`);
  fs.rmSync(updater.stagedPath(mirrorVersion), { force: true });

  await new Promise((r) => server.close(r));

  // The no-click path itself: the main process announces an update, the renderer installs it
  // as soon as the game is closed, and it is skipped when the user switched it off.
  const preloadSrc = fs.readFileSync(path.join(ROOT, 'src/main/preload.js'), 'utf8');
  const rendererSrc = fs.readFileSync(path.join(ROOT, 'src/renderer/app.js'), 'utf8');
  check('the renderer is told an update exists', /onUpdateAvailable:/.test(preloadSrc));
  check('auto install defaults to on in settings', /autoInstall: true/.test(fs.readFileSync(path.join(ROOT, 'src/main/settings.js'), 'utf8')));
  check('auto install waits for the game to close', /autoInstallWhenIdle/.test(rendererSrc) && /state\.running\) break;/.test(rendererSrc));
  check('the auto path is skipped when the user turned it off', /const autoInstall = !s \|\| s\.autoInstall !== false;/.test(rendererSrc));
  check('the check itself is skipped when autoUpdate is off', /if \(s\.autoUpdate === false\) return;/.test(fs.readFileSync(path.join(ROOT, 'src/main/main.js'), 'utf8')));

  /* ------------- 8. account: one surface in the top-right chip, many accounts ------------- */
  // The Account page was removed on request, and the account area grew multi-account support.
  // These pin both: one surface only, every old control still reachable, heads cropped where
  // they can actually load, and one stored file per account.
  console.log('\n=== 8. account lives in the top-right chip, with multiple accounts ===');
  const html8 = fs.readFileSync(path.join(ROOT, 'src/renderer/index.html'), 'utf8');
  const app8 = fs.readFileSync(path.join(ROOT, 'src/renderer/app.js'), 'utf8');
  const pre8 = fs.readFileSync(path.join(ROOT, 'src/main/preload.js'), 'utf8');
  const main8 = fs.readFileSync(path.join(ROOT, 'src/main/main.js'), 'utf8');

  check('no Account entry in the sidebar', !/data-view="account"/.test(html8));
  check('no Account page section left', !/id="view-account"/.test(html8));
  // Capture up to the next modal section: a lazy </div></div> stops inside the card row.
  const modal8 = (html8.match(/id="authModal"[\s\S]*?(?=<!-- ===== delete-mod confirmation)/) || [''])[0];
  for (const id of ['accSignIn', 'accSignOut', 'accRefresh', 'accBigAvatar', 'accMeta', 'loginLog', 'loginState']) {
    check(`the account panel owns #${id}`, modal8.includes(`id="${id}"`), id);
  }
  check('the chip opens the account panel', /openAccountPanel/.test(app8) && /'accountBox'\)\.addEventListener\('click'/.test(app8));
  check('no stale reference to the removed account card', !/\$\('accCard'\)/.test(app8));

  check('heads are cropped in the main process', /nativeImage\.createFromBuffer/.test(main8) && /function headForUrl/.test(main8));
  check('the renderer asks main for every head', /api\.accountHead\(active\.url\)/.test(app8));
  check('the broken canvas cropper is gone', !/skinHeadUrl/.test(app8));
  check('no third-party head service', !/mc-heads|minotar|crafatar/i.test(app8 + main8));

  check('one file per account', /accountsDir/.test(main8) && /accounts-index\.json/.test(main8));
  check('switching refreshes the session seam', /'accounts:switch'/.test(main8) && /ensureChain\(data\)/.test(main8));
  check('removing the active account falls back to another', /'accounts:remove'/.test(main8) && /const rest = await listAccounts\(\);/.test(main8));
  check('preload exposes list / switch / remove', /accountsList:/.test(pre8) && /accountsSwitch:/.test(pre8) && /accountsRemove:/.test(pre8));
  check('the modal renders one row per account', /renderAccountList/.test(app8) && /id="accRows"/.test(html8));
  check('sign-in stays usable as "add another account"', /\$\('accSignIn'\)\.textContent = I18N\.t\('acc\.add'\)|\+ Add account/.test(app8));

  /* ------------------------- 9. crash detector ---------------------------- */
  console.log('\n=== 9. crash detector: an exit the player did not ask for gets what to do next ===');
  const crash = require(path.join(ROOT, 'src/main/crash.js'));
  // exit classification
  check('a clean quit is not a crash', !crash.isCrashExit(0, null));
  check('SIGTERM exit code is not a crash', !crash.isCrashExit(143, null));
  check('the launcher STOP button never reads as a crash', !crash.isCrashExit(1, null, { killedByLauncher: true }));
  check('any unhandled signal is a crash', crash.isCrashExit(0, 'SIGSEGV'));
  check('a non-zero exit is a crash', crash.isCrashExit(1, null));
  // report discovery on real files
  const tmp9 = fs.mkdtempSync(path.join(require('os').tmpdir(), 'voidcrash-'));
  fs.mkdirSync(path.join(tmp9, 'crash-reports'));
  const repVoid = path.join(tmp9, 'crash-reports', 'crash-2026-11-06-client.txt');
  fs.writeFileSync(repVoid, [
    '---- Minecraft Crash Report ----',
    '// I let you down. Sorry :(',
    '',
    'Time: 2026-11-06',
    'Description: Mod loading error: mixin apply failed',
    'java.lang.IllegalStateException: Mixin apply failed: voidfps.mixins.json',
    '\tat id.agung.voidfps.mixin.PlayerListHudMixin',
  ].join('\n'));
  const stale = new Date(Date.now() - 60000);
  fs.utimesSync(repVoid, stale, stale);
  const repNew = path.join(tmp9, 'crash-reports', 'crash-2026-11-06_2-client.txt');
  fs.writeFileSync(repNew, '---- Minecraft Crash Report ----\n// audio\nDescription: Buffer overflow\njava.lang.ArrayIndexOutOfBoundsException: 12\n');
  check('only crash reports newer than the session are used',
    crash.latestCrashReport(path.join(tmp9, 'crash-reports'), Date.now() - 30000) === repNew);
  check('crash reports older than the session are ignored',
    !crash.latestCrashReport(path.join(tmp9, 'crash-reports'), Date.now() + 1000));
  check('a missing crash-reports folder answers null',
    crash.latestCrashReport(path.join(tmp9, 'nowhere'), 0) === null);
  // summarization: every crash must leave the player with next steps
  const sVoid = crash.summarize({ code: 1, reportText: fs.readFileSync(repVoid, 'utf8'), reportFile: repVoid });
  const sMem = crash.summarize({ code: 1, reportText: 'Description: java.lang.OutOfMemoryError: Java heap space' });
  const sBare = crash.summarize({ code: 1, signal: null, reportText: '', reportFile: '' });
  check('the summary always tells the user what to do next', [
    sVoid, sMem, sBare,
  ].every((s) => Array.isArray(s.steps) && s.steps.length > 0));
  check('every step is a concrete instruction', [
    sVoid, sMem, sBare,
  ].every((s) => s.steps.every((x) => typeof x === 'string' && x.length > 8)));
  check('a voidfps stack frame names the bundled mod', /VOID Client/.test(sVoid.suspect), sVoid.suspect);
  check('an OutOfMemoryError says to lower the memory setting', sMem.steps.some((s) => /lower the memory/i.test(s)));
  check('no report still yields log-based guidance', sBare.steps.some((s) => /log|PLAY/i.test(s)));
  check('the copy block carries the suspect and the numbered steps',
    /Suspect: VOID Client/.test(crash.toText(sVoid)) && /1\. /.test(crash.toText(sVoid)));
  // wiring
  const h9 = fs.readFileSync(path.join(ROOT, 'src/renderer/index.html'), 'utf8');
  const a9 = fs.readFileSync(path.join(ROOT, 'src/renderer/app.js'), 'utf8');
  const p9 = fs.readFileSync(path.join(ROOT, 'src/main/preload.js'), 'utf8');
  const m9 = fs.readFileSync(path.join(ROOT, 'src/main/main.js'), 'utf8');
  check('the crash modal exists with the relief buttons',
    ['crashModal', 'crashRelaunch', 'crashOpenReport', 'crashCopy', 'crashSteps'].every((id) => h9.includes(`id="${id}"`)));
  check('onCrash is bridged through preload and consumed by the renderer',
    /onCrash:/.test(p9) && /launch:crash/.test(p9) && /launch:crash/.test(m9) && /api\.onCrash\(/.test(a9));
  check('STOP sets the kill flag before the exit event fires', m9.includes('mcKilled = true;') && m9.includes('mcKilled = false;'));
  check('every exit goes through isCrashExit', /crash\.isCrashExit\(code, signal, \{ killedByLauncher: mcKilled \}\)/.test(m9));
  check('launch:kill marks the kill first', /ipcMain\.handle\('launch:kill'[\s\S]{0,160}mcKilled = true;/.test(m9));
  check('uncaught exceptions get a dialog and a breadcrumb file', /uncaughtException/.test(m9) && /crash-logs/.test(m9));
  check('a dead renderer offers Reload, not a frozen window', /render-process-gone/.test(m9) && /webContents\.reload\(\)/.test(m9));
  check('the clipboard surface is capped', /length <= 20000/.test(m9));
  check('the crash copy is English only', (() => {
    const block = a9.slice(a9.indexOf('Crash detector:'), a9.indexOf('* The PLAY button'));
    return block.length > 100 && !/(nggak|jangan|kamu|udah|selesai|sudah|kayak|sayang|mau|pakai)/i.test(block);
  })());
  fs.rmSync(tmp9, { recursive: true, force: true });

  /* ------------------- 10. i18n & first-run onboarding --------------------- */
  console.log('\n=== 10. i18n: English default, a real language pick on first run ===');
  // The dictionary must load in a bare VM: same globals the renderer gives it.
  const i18n = (() => {
    const ctx = { window: {}, document: null };
    require('vm').runInNewContext(fs.readFileSync(path.join(ROOT, 'src/renderer/i18n.js'), 'utf8'), ctx, { filename: 'i18n.js' });
    return ctx.window.I18N;
  })();
  check('the dictionary loads and defaults to English', typeof i18n.t === 'function' && i18n.defaultLang() === 'en');
  const en9keys = Object.keys(i18n.DICTS.en).sort();
  for (const code of ['id', 'ja', 'ko']) {
    const keys = Object.keys(i18n.DICTS[code]).sort();
    const missing = en9keys.filter((k) => !keys.includes(k));
    const extra = keys.filter((k) => !en9keys.includes(k));
    check(`${code} has exactly the English key set`, missing.length === 0 && extra.length === 0,
      missing.length ? `missing ${missing.slice(0, 3).join(',')}` : extra.length ? `extra ${extra.slice(0, 3).join(',')}` : '');
  }
  check('a missing translation falls back to English, never empty',
    i18n.DICTS.en['nonexistent.key'] === undefined && i18n.t('nonexistent.key') === 'nonexistent.key');
  i18n.setLang('id');
  check('setLang repaints through t()', i18n.t('nav.play') === 'Main' && i18n.t('home.play') === 'MULAI');
  i18n.setLang('ja');
  check('ja and ko cover the onboarding copy', ['ja', 'ko'].every((c) => /言語|언어|Bahasa/.test(i18n.DICTS[c]['onb.lang_h'])));
  i18n.setLang('en');
  check('unknown codes are refused and English stays', i18n.setLang('xx') === false && i18n.t('nav.play') === 'Play');

  const h10 = fs.readFileSync(path.join(ROOT, 'src/renderer/index.html'), 'utf8');
  const a10 = fs.readFileSync(path.join(ROOT, 'src/renderer/app.js'), 'utf8');
  const st10 = fs.readFileSync(path.join(ROOT, 'src/main/settings.js'), 'utf8');
  const onb = (h10.match(/<div class="modal-backdrop" id="onbModal"[\s\S]*?<\/div>\n<\/div>/) || [''])[0];
  check('onboarding modal exists with both steps', onb.includes('id="onbStepLang"') && onb.includes('id="onbStepAccount"'));
  for (const id of ['onbLangs', 'onbToAccount', 'onbSignIn', 'onbSkip']) {
    check(`the wizard owns #${id}`, onb.includes(`id="${id}"`), id);
  }
  check('onboarding is gated on the settings flag, once', /if \(s\.onboarded\) return;/.test(a10) && /initOnboarding\(s\)/.test(a10));
  check('the language choice is persisted through patchSettings', /patchSettings\(\{ lang: onbLang, onboarded: true \}\)/.test(a10));
  check('the picker repaints the UI in the chosen language at once', /onbLang = l\.code;\s*\n\s*I18N\.setLang\(onbLang\);/.test(a10));
  check('skipping the account step is a first-class outcome', /\$\('onbSkip'\)\.addEventListener/.test(a10));
  check('English is the hard default everywhere', /lang: 'en'/.test(st10) && /s\.lang \|\| 'en'/.test(a10));
  check('Settings owns a language switcher bound to the same store', h10.includes('id="sLang"') && /\$\('sLang'\)\.addEventListener\('change'/.test(a10));
  check('the wizard copy is translated in the markup', h10.includes('data-i18n="onb.welcome"') && h10.includes('data-i18n="onb.acc_h"'));
  check('data-i18n attr set on the static chrome', ['data-i18n="nav.play"', 'data-i18n="home.play"', 'data-i18n-ph="mods.search_ph"', 'data-i18n-html="home.title"'].every((a) => h10.includes(a)));
  check('i18n.js loads before app.js', h10.indexOf('i18n.js') !== -1 && h10.indexOf('i18n.js') < h10.indexOf('app.js'));
  // one real dictionary execution: Indonesian chrome must repaint the play button label
  check('the play/stop labels are t() driven, not hardcoded English', !/running \? 'STOP GAME' : 'PLAY'/.test(a10));

  console.log(`\n${pass} passed, ${fail} failed`);
  process.exit(fail ? 1 : 0);
})();
